/** Atomic front-desk registration: (new or existing) patient → OPD ticket → invoice → payment → queue token. Send an `Idempotency-Key` header so a retry never double-charges. */
export interface RegistrationIn {
  /** Existing patient (from /patients/search) */
  patient_id?: number | null;
  /** Full intake form for a new patient */
  new_patient?: PatientCreate | null;
  /** Target doctor (employee id); or give department_id */
  doctor_id?: number | null;
  department_id?: number | null;
  /** Override the consultation service/fee */
  service_id?: number | null;
  source?: "WalkIn" | "Emergency" | "Referred" | "ReturnVisit";
  /** Within your discount ceiling (else request a waiver) */
  discount_amount?: number | string;
  discount_reason?: string | null;
  /** Pay now. Omit to issue an unpaid slip (e.g. to request a waiver/credit). */
  payment?: PaymentIn | null;
  /** ER/Trauma: skip the outstanding-dues block and payment-before-queue */
  emergency_bypass?: boolean;
  /** Needs permission opd.ticket.ar_override when dues block applies */
  ar_override_reason?: string | null;
}

